<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('student');$uid=(int)$_SESSION['user_id'];$q=$conn->prepare('SELECT st.student_id FROM student_account_requests r JOIN students st ON st.student_id=r.student_id WHERE r.user_id=? AND r.request_status="approved"');$q->bind_param('i',$uid);$q->execute();$student=$q->get_result()->fetch_assoc();if(!$student){http_response_code(403);exit('Verified student record required.');}$sid=(int)$student['student_id'];$q=$conn->prepare('SELECT y.school_year_name,sub.subject_code,sub.subject_name,gp.period_name,g.grade_value FROM grades g JOIN teacher_assignments a ON a.teacher_assignment_id=g.teacher_assignment_id JOIN subjects sub ON sub.subject_id=a.subject_id JOIN grading_periods gp ON gp.grading_period_id=g.grading_period_id JOIN school_years y ON y.school_year_id=gp.school_year_id WHERE g.student_id=? AND g.grade_status="released" ORDER BY y.school_year_id DESC,gp.period_order,sub.subject_name');$q->bind_param('i',$sid);$q->execute();$rows=$q->get_result();page_start('Grades');echo '<h1>Grades</h1><div class="tablewrap"><table><tr><th>School year</th><th>Subject</th><th>Grading period</th><th>Grade</th></tr>';while($g=$rows->fetch_assoc())echo '<tr><td>'.e($g['school_year_name']).'</td><td>'.e($g['subject_code'].' — '.$g['subject_name']).'</td><td>'.e($g['period_name']).'</td><td>'.e($g['grade_value']).'</td></tr>';echo '</table></div>';page_end();
